-- SpareSlot core schema (PostgreSQL 16, Flyway).
-- Owned by the contract session. After hour 2 do not edit this file: add a new migration instead
-- (backend uses V10-V19, infra and seed data use V90+).
--
-- Design rules this schema enforces, so the application cannot forget them:
--   1. No two live bookings overlap on one resource (exclusion constraint).
--   2. A booking only moves along edges listed in booking_transitions (guard trigger).
--   3. approved, rejected, waitlisted and cancelled bookings always carry a reason.
--   4. audit_events is append-only: updates, deletes and truncates are refused.

CREATE EXTENSION IF NOT EXISTS btree_gist;

-- ---------------------------------------------------------------- people and organisations

CREATE TABLE organisations (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name        text NOT NULL UNIQUE,
    kind        text NOT NULL CHECK (kind IN ('college_lab', 'makerspace', 'studio', 'other')),
    description text NOT NULL DEFAULT '',
    location    text NOT NULL DEFAULT '',
    verified    boolean NOT NULL DEFAULT false,   -- set by an admin; only verified organisations list resources
    verified_by uuid,
    verified_at timestamptz,
    created_at  timestamptz NOT NULL DEFAULT now(),
    CHECK (verified = (verified_at IS NOT NULL))
);

CREATE TABLE teams (
    id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name       text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE users (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    email         text NOT NULL UNIQUE CHECK (email = lower(email)),
    password_hash text NOT NULL,                  -- BCrypt, written by Spring Security's encoder
    full_name     text NOT NULL,
    role          text NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'owner', 'manager', 'admin')),
    borrower_type text CHECK (borrower_type IN ('student', 'researcher', 'creator', 'startup_team')),
    affiliation   text NOT NULL DEFAULT '',       -- college or institute; '' = independent (deposit applies)
    team_id       uuid REFERENCES teams (id),     -- a team shares one quota
    org_id        uuid REFERENCES organisations (id),
    status        text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended')),
    created_at    timestamptz NOT NULL DEFAULT now(),
    -- owners and managers belong to exactly one organisation; users and admins to none
    CHECK ((role IN ('owner', 'manager')) = (org_id IS NOT NULL))
);

ALTER TABLE organisations
    ADD CONSTRAINT organisations_verified_by_fk FOREIGN KEY (verified_by) REFERENCES users (id);

-- A verification request is a credential in status 'pending'. A manager reviews it.
CREATE TABLE credentials (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    org_id        uuid REFERENCES organisations (id),   -- organisation asked to review; NULL = any manager
    kind          text NOT NULL CHECK (kind IN ('student_id', 'research_affiliation', 'creator_portfolio',
                                                 'team_registration', 'safety_induction', 'other')),
    evidence      text NOT NULL DEFAULT '',
    status        text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'verified', 'rejected')),
    reviewed_by   uuid REFERENCES users (id),
    reviewed_at   timestamptz,
    review_reason text,
    expires_at    timestamptz,
    created_at    timestamptz NOT NULL DEFAULT now(),
    CHECK (status = 'pending'
           OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL AND btrim(coalesce(review_reason, '')) <> ''))
);

-- ---------------------------------------------------------------- resources

CREATE TABLE resources (
    id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id            uuid NOT NULL REFERENCES organisations (id),
    name              text NOT NULL,
    category          text NOT NULL CHECK (category IN ('equipment', 'space')),
    description       text NOT NULL DEFAULT '',
    location          text NOT NULL DEFAULT '',
    conditions        text NOT NULL DEFAULT '',     -- the owner's conditions of use, shown before a request
    max_booking_hours integer NOT NULL DEFAULT 4 CHECK (max_booking_hours > 0),
    weekly_hour_cap   integer NOT NULL DEFAULT 8 CHECK (weekly_hour_cap > 0),
    deposit_minor     integer NOT NULL DEFAULT 0 CHECK (deposit_minor >= 0),  -- refundable, independents only
    active            boolean NOT NULL DEFAULT true,
    created_at        timestamptz NOT NULL DEFAULT now()
);

-- Eligibility: a borrower needs a verified, unexpired credential of every kind listed here.
CREATE TABLE resource_requirements (
    resource_id     uuid NOT NULL REFERENCES resources (id) ON DELETE CASCADE,
    credential_kind text NOT NULL CHECK (credential_kind IN ('student_id', 'research_affiliation',
                                                             'creator_portfolio', 'team_registration',
                                                             'safety_induction', 'other')),
    PRIMARY KEY (resource_id, credential_kind)
);

-- ---------------------------------------------------------------- bookings

CREATE TABLE bookings (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    resource_id     uuid NOT NULL REFERENCES resources (id),
    requester_id    uuid NOT NULL REFERENCES users (id),
    team_id         uuid REFERENCES teams (id),    -- copied from the requester when the request is made
    start_at        timestamptz NOT NULL,
    end_at          timestamptz NOT NULL,
    purpose         text NOT NULL,
    status          text NOT NULL DEFAULT 'requested'
                    CHECK (status IN ('requested', 'approved', 'rejected', 'waitlisted',
                                      'checked_in', 'returned', 'closed', 'cancelled')),
    decision_reason text,
    decided_by      uuid REFERENCES users (id),    -- NULL when the system decided (auto-waitlist, promotion)
    decided_at      timestamptz,
    deposit_minor   integer NOT NULL DEFAULT 0 CHECK (deposit_minor >= 0),
    deposit_status  text NOT NULL DEFAULT 'none' CHECK (deposit_status IN ('none', 'held', 'refunded', 'forfeited')),
    checked_in_at   timestamptz,
    returned_at     timestamptz,
    closed_at       timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    CHECK (end_at > start_at),
    -- a decision without a reason is refused by the database itself
    -- (coalesce matters: btrim(NULL) <> '' is NULL, and a CHECK treats NULL as a pass)
    CHECK (status NOT IN ('approved', 'rejected', 'waitlisted', 'cancelled')
           OR btrim(coalesce(decision_reason, '')) <> ''),
    -- no double booking: approved and checked-in bookings cannot overlap on a resource
    CONSTRAINT bookings_no_overlap EXCLUDE USING gist (
        resource_id WITH =,
        tstzrange(start_at, end_at) WITH &&
    ) WHERE (status IN ('approved', 'checked_in'))
);

CREATE INDEX bookings_resource_start_idx ON bookings (resource_id, start_at);
CREATE INDEX bookings_requester_idx ON bookings (requester_id, created_at DESC);
CREATE INDEX bookings_status_idx ON bookings (status);

-- The state machine as data. The application reads it to show or hide buttons;
-- the trigger below refuses any status change that is not listed here.
-- allowed_roles: 'requester' = a user acting on their own booking; the others are users.role values;
-- 'system' = the scheduler or the auto-waitlist.
CREATE TABLE booking_transitions (
    from_status     text NOT NULL,
    to_status       text NOT NULL,
    allowed_roles   text[] NOT NULL,
    requires_reason boolean NOT NULL,
    PRIMARY KEY (from_status, to_status)
);

INSERT INTO booking_transitions (from_status, to_status, allowed_roles, requires_reason) VALUES
    ('requested',  'approved',   '{owner,manager}',                     true),
    ('requested',  'rejected',   '{owner,manager}',                     true),
    ('requested',  'waitlisted', '{owner,manager,system}',              true),
    ('requested',  'cancelled',  '{requester}',                         true),
    ('waitlisted', 'approved',   '{owner,manager,system}',              true),
    ('waitlisted', 'rejected',   '{owner,manager}',                     true),
    ('waitlisted', 'cancelled',  '{requester}',                         true),
    ('approved',   'checked_in', '{owner,manager}',                     false),
    ('approved',   'cancelled',  '{requester,owner,manager}',           true),
    ('checked_in', 'returned',   '{owner,manager}',                     false),
    ('returned',   'closed',     '{owner,manager,system}',              false);

-- Refuses a status change that is not listed above. When the change needs a reason, the statement must
-- supply a NEW one (a reason left over from the previous decision does not count), and decided_at is stamped.
CREATE FUNCTION bookings_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    rule booking_transitions%ROWTYPE;
BEGIN
    IF NEW.status <> OLD.status THEN
        SELECT * INTO rule FROM booking_transitions t
        WHERE t.from_status = OLD.status AND t.to_status = NEW.status;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'illegal booking transition % -> %', OLD.status, NEW.status
                USING ERRCODE = 'check_violation';
        END IF;
        IF rule.requires_reason THEN
            IF btrim(coalesce(NEW.decision_reason, '')) = ''
               OR NEW.decision_reason IS NOT DISTINCT FROM OLD.decision_reason THEN
                RAISE EXCEPTION 'transition % -> % needs a new reason', OLD.status, NEW.status
                    USING ERRCODE = 'check_violation';
            END IF;
            NEW.decided_at := now();
        END IF;
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
END $$;

CREATE TRIGGER bookings_guard_trg BEFORE UPDATE ON bookings
    FOR EACH ROW EXECUTE FUNCTION bookings_guard();

CREATE TABLE booking_extensions (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    booking_id      uuid NOT NULL REFERENCES bookings (id) ON DELETE CASCADE,
    requested_end_at timestamptz NOT NULL,
    reason          text NOT NULL,                  -- why the borrower needs more time
    status          text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested', 'approved', 'rejected')),
    decision_reason text,
    decided_by      uuid REFERENCES users (id),
    decided_at      timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    CHECK (status = 'requested' OR btrim(coalesce(decision_reason, '')) <> '')
);

-- Approving an extension updates bookings.end_at; the overlap constraint then refuses a clash.

-- ---------------------------------------------------------------- condition, incidents

CREATE TABLE condition_records (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    booking_id  uuid NOT NULL REFERENCES bookings (id) ON DELETE CASCADE,
    phase       text NOT NULL CHECK (phase IN ('check_in', 'return')),
    rating      text NOT NULL CHECK (rating IN ('good', 'minor_wear', 'damaged')),
    notes       text NOT NULL DEFAULT '',
    photo_path  text,
    recorded_by uuid NOT NULL REFERENCES users (id),
    recorded_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (booking_id, phase),
    CHECK (rating <> 'damaged' OR btrim(notes) <> '')
);

CREATE TABLE incidents (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    booking_id  uuid NOT NULL REFERENCES bookings (id),
    resource_id uuid NOT NULL REFERENCES resources (id),
    kind        text NOT NULL CHECK (kind IN ('damage', 'delay', 'conflict', 'pre_existing_damage', 'dispute')),
    description text NOT NULL,
    status      text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'under_review', 'resolved')),
    raised_by   uuid NOT NULL REFERENCES users (id),
    raised_at   timestamptz NOT NULL DEFAULT now(),
    resolved_by uuid REFERENCES users (id),
    resolved_at timestamptz,
    resolution  text,
    CHECK (status <> 'resolved'
           OR (resolved_by IS NOT NULL AND resolved_at IS NOT NULL AND btrim(coalesce(resolution, '')) <> ''))
);

CREATE INDEX incidents_open_idx ON incidents (resource_id) WHERE status <> 'resolved';

-- ---------------------------------------------------------------- notifications and audit

CREATE TABLE notifications (
    id          bigserial PRIMARY KEY,
    user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    message     text NOT NULL,
    entity_type text,
    entity_id   uuid,
    read_at     timestamptz,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX notifications_unread_idx ON notifications (user_id, created_at DESC) WHERE read_at IS NULL;

-- One row per decision or state change, written by the service in the same transaction as the change.
CREATE TABLE audit_events (
    id          bigserial PRIMARY KEY,
    at          timestamptz NOT NULL DEFAULT now(),
    actor_id    uuid,                                -- NULL for the system
    actor_role  text NOT NULL CHECK (actor_role IN ('user', 'owner', 'manager', 'admin', 'system')),
    action      text NOT NULL,                       -- e.g. booking.approved, credential.verified
    entity_type text NOT NULL,                       -- booking, credential, resource, organisation, incident, extension
    entity_id   uuid NOT NULL,
    from_status text,
    to_status   text,
    reason      text,
    details     jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE INDEX audit_events_entity_idx ON audit_events (entity_type, entity_id, at);

CREATE FUNCTION audit_events_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit_events is append-only' USING ERRCODE = 'insufficient_privilege';
END $$;

CREATE TRIGGER audit_events_no_change BEFORE UPDATE OR DELETE ON audit_events
    FOR EACH ROW EXECUTE FUNCTION audit_events_immutable();
CREATE TRIGGER audit_events_no_truncate BEFORE TRUNCATE ON audit_events
    FOR EACH STATEMENT EXECUTE FUNCTION audit_events_immutable();

-- ---------------------------------------------------------------- fair-use views

-- Hours already committed per resource, per quota subject (a team, or the user if they have none), per week.
-- Weeks start on Monday, UTC. Compare hours with resources.weekly_hour_cap.
CREATE VIEW v_weekly_usage AS
SELECT b.resource_id,
       COALESCE(b.team_id, b.requester_id)                                  AS subject_id,
       date_trunc('week', b.start_at AT TIME ZONE 'UTC')                    AS week_start,
       SUM(EXTRACT(EPOCH FROM (b.end_at - b.start_at)) / 3600.0)::numeric(8, 2) AS hours
FROM bookings b
WHERE b.status IN ('approved', 'checked_in', 'returned', 'closed')
GROUP BY 1, 2, 3;

-- Waitlist order: fewest hours used in the last 30 days first, then the earliest request.
CREATE VIEW v_recent_usage_30d AS
SELECT COALESCE(b.team_id, b.requester_id)                                  AS subject_id,
       SUM(EXTRACT(EPOCH FROM (b.end_at - b.start_at)) / 3600.0)::numeric(8, 2) AS hours
FROM bookings b
WHERE b.status IN ('approved', 'checked_in', 'returned', 'closed')
  AND b.start_at >= now() - interval '30 days'
GROUP BY 1;
